// Helper to look up vehicle by bus number or route
export function findVehicleByBusNumber(busNumber: string): FleetVehicle | undefined {
  if (!busNumber) return undefined;
  const clean = busNumber.trim().replace(/^6-/, '').replace(/^3-/, '').replace(/^กปด\.\d+\s*/, '');
  return BMTA_DISTRICT_6_FLEET.find(
    (v) => v.busNumber === busNumber.trim() || v.busNumber === clean || v.busNumber.endsWith(clean)
  );
}

export function findVehicleByLicensePlate(plate: string): FleetVehicle | undefined {
  if (!plate) return undefined;
  return BMTA_DISTRICT_6_FLEET.find((v) => v.licensePlate === plate.trim());
}

export function findVehicleByRowNo(rowNo: number): FleetVehicle | undefined {
  return BMTA_DISTRICT_6_FLEET.find((v) => v.no === rowNo);
}
